  const HEADING = /^(#{1,6})\s+(.*)$/;
  const BULLET = /^[-*+]\s+(.*)$/;
  const NUMBERED = /^\d+[.)]\s+(.*)$/;
  const RULE = /^(?:\*\s*){3,}$|^(?:-\s*){3,}$|^(?:_\s*){3,}$/;
  const TABLE_DIVIDER = /^\|?[\s:|-]*-[\s:|-]*\|[\s:|-]*$/;

  /** Inline markup, applied to already-escaped text. */
